// Decides the alarm level. Deliberately here rather than in the page, so the
// terminal watcher and the browser page cannot disagree about what counts as an
// alarm — two alerting tools with different opinions is worse than one.
//
// Must never throw: an error here would leave the alarm page with nothing to
// show, which looks identical to a quiet queue.
const row = $input.item.json || {};
const num = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };

// The Postgres node was told to continue on error, so a database failure arrives
// here as an error payload rather than a row. That is itself an alarm: if this
// cannot be read, nobody is watching anything.
if (row.error || row.unacknowledged === undefined) {
  return {
    json: {
      level: 'critical',
      headline: 'CANNOT READ THE QUEUE',
      detail: 'The alarm cannot reach the database. Check the node before trusting a quiet screen.',
      action: 'On the node: docker compose ps, then docker compose logs postgres',
      unreadable: true,
      at: new Date().toISOString()
    }
  };
}

const critical_past_deadline = num(row.critical_past_deadline);
const past_deadline = num(row.past_deadline);
const unacknowledged_critical = num(row.unacknowledged_critical);
const model_failures = num(row.model_failures_last_hour);
const injections = num(row.injections_last_hour);
const needs_review_open = num(row.needs_review_open);

let level = 'ok';
let headline = 'Queue is current';
let detail = '';
let action = '';

if (critical_past_deadline > 0) {
  // The one unambiguous alarm: a life-threatening request nobody has picked up
  // inside its deadline.
  level = 'critical';
  headline = critical_past_deadline + ' CRITICAL past deadline';
  detail = 'Nobody has acknowledged ' + (critical_past_deadline === 1 ? 'a Critical request' : critical_past_deadline + ' Critical requests') + ' within 15 minutes.';
  action = 'Open review_pile / active_queue now. Acknowledge and set assigned_to.';
} else if (model_failures > 0) {
  // Not a queue problem. Requests are still stored and escalated, but nothing is
  // being sorted, so the queue is arriving as a flat pile of Criticals.
  level = 'warning';
  headline = 'Triage is not running';
  detail = model_failures + ' request(s) in the last hour were stored without triage because the model was unreachable.';
  action = 'Fix the node, do not hand-triage: docker compose logs ollama';
} else if (past_deadline > 0) {
  level = 'warning';
  headline = past_deadline + ' past deadline';
  detail = 'Requests are waiting longer than their severity allows.';
  action = 'Work the queue; if arrivals exceed throughput you need more coordinators.';
} else if (needs_review_open > 0) {
  level = 'attention';
  headline = needs_review_open + ' awaiting review';
  detail = 'Flagged requests a human has not read yet.';
  action = 'Work review_pile, worst reason first.';
} else if (unacknowledged_critical > 0) {
  level = 'attention';
  headline = unacknowledged_critical + ' new Critical';
  detail = 'Inside deadline, but unacknowledged.';
  action = 'Acknowledge and assign.';
}

if (injections > 0 && level === 'ok') {
  level = 'attention';
  headline = injections + ' suspected injection';
  detail = 'Instruction-shaped text in submitted messages. Triage output for those rows is not trusted.';
  action = 'Read those rows in review_pile yourself.';
}

return {
  json: {
    level,
    headline,
    detail,
    action,
    counts: {
      total_open: num(row.total_open),
      unacknowledged: num(row.unacknowledged),
      unacknowledged_critical,
      past_deadline,
      critical_past_deadline,
      needs_review_open,
      dispatched_open: num(row.dispatched_open),
      arrived_last_hour: num(row.arrived_last_hour),
      model_failures_last_hour: model_failures,
      injections_last_hour: injections,
      oldest_unacknowledged_min: num(row.oldest_unacknowledged_min)
    },
    review_reasons: row.review_reasons || [],
    at: new Date().toISOString()
  }
};
